   $username=trim($body['username']??'');$collision=one('SELECT id FROM accounts WHERE username=?',[$username]);if($collision&&$collision['id']!==$id)fail(409,'Username unavailable');if(strlen($username)<1||strlen($username)>190)fail(422,'Username required');
