  else fail(405,'Read-only resource');
  audit('admin_'.$kind,$id);query('UPDATE organizations SET permission_epoch=sequence+1,sequence=sequence+1 WHERE id=?',[org()]);$pdo->commit();json_out(['ok'=>true]);
 }
