if(str_starts_with($path,'admin/reports/')&&$method==='GET'){
 role(['administrator','content_manager','report_viewer']);$type=substr($path,14);$args=[org()];$where='organization_id=?';
 if(!empty($_GET['location'])){$where.=' AND location_id=?';$args[]=require_id($_GET['location']);}
 if(!empty($_GET['from'])){$where.=' AND occurred_at_utc>=?';$args[]=gmdate('Y-m-d H:i:s',strtotime($_GET['from'])?:0);}
 if(!empty($_GET['to'])){$where.=' AND occurred_at_utc<=?';$args[]=gmdate('Y-m-d H:i:s',strtotime($_GET['to'].' 23:59:59')?:0);}
 $events=array_map('payload',rows("SELECT payload FROM usage_events WHERE $where ORDER BY occurred_at_utc",$args));
 if($type==='safety')$result=array_values(array_filter($events,fn($e)=>$e['event_type']==='content_presented'&&($e['content_type']??'')==='external-video'&&!empty($e['safety'])));
 elseif($type==='skips')$result=array_values(array_filter($events,fn($e)=>in_array($e['event_type'],['broadcast_skipped','slide_skipped'],true)));
 elseif($type==='content'){$counts=[];foreach($events as $e){if($e['event_type']!=='content_presented')continue;$key=$e['location_id'].':'.$e['content_id'].':'.($e['content_version']??0);if(!isset($counts[$key]))$counts[$key]=['id'=>$key,'content_id'=>$e['content_id'],'title'=>$e['title'],'version'=>$e['content_version'],'location_id'=>$e['location_id'],'presentations'=>0,'last_presented'=>''];$counts[$key]['presentations']++;$counts[$key]['last_presented']=max($counts[$key]['last_presented'],$e['occurred_at_utc']);}$result=array_values($counts);}
 elseif($type==='meetings'){$query='SELECT payload FROM meetings WHERE organization_id=?';$ma=[org()];if(!empty($_GET['location'])){$query.=' AND location_id=?';$ma[]=$_GET['location'];}$result=array_map('payload',rows($query.' ORDER BY created_at DESC',$ma));}
 elseif($type==='locations'){$result=rows('SELECT l.id,l.name,(SELECT MAX(m.created_at) FROM meetings m WHERE m.organization_id=l.organization_id AND m.location_id=l.id AND m.status=\'completed\') last_meeting,(SELECT MAX(d.last_sync) FROM devices d JOIN accounts a ON a.organization_id=d.organization_id AND a.id=d.account_id WHERE a.organization_id=l.organization_id AND a.location_id=l.id) last_sync,(SELECT COUNT(*) FROM devices d JOIN accounts a ON a.organization_id=d.organization_id AND a.id=d.account_id WHERE a.organization_id=l.organization_id AND a.location_id=l.id AND d.revoked=0 AND d.last_seen>DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)) active_devices FROM locations l WHERE l.organization_id=?',[org()]);}
 elseif(in_array($type,['broadcasts','requirements'],true)){$result=[];foreach(rows('SELECT payload FROM records WHERE organization_id=? AND kind=?',[org(),'broadcasts']) as $r){$b=payload($r);if($type==='requirements'&&$b['importance']!=='required')continue;foreach(rows('SELECT id,name FROM locations WHERE organization_id=?',[org()]) as $l){if(!empty($b['locations'])&&!in_array($l['id'],$b['locations'],true))continue;$shown=array_filter($events,fn($e)=>($e['broadcast_id']??'')===$b['id']&&$e['location_id']===$l['id']&&$e['event_type']==='broadcast_presented');$skips=array_filter($events,fn($e)=>($e['broadcast_id']??'')===$b['id']&&$e['location_id']===$l['id']&&$e['event_type']==='broadcast_skipped');$successful=array_filter($shown,fn($p)=>!array_filter($skips,fn($s)=>$s['meeting_id']===$p['meeting_id']&&($s['slide_id']??null)===($p['slide_id']??null)));$result[]=['id'=>$b['id'].':'.$l['id'],'broadcast'=>$b['title'],'location'=>$l['name'],'presented'=>count($shown),'skipped'=>count($skips),'status'=>count($successful)>0?'Presented':'Not completed','reasons'=>implode(' | ',array_column($skips,'reason'))];}}}
 else $result=$events;
 json_out(['rows'=>$result]);
}
